mapper.sql:
WHERE p.archived = #{filter.archived}

    AND (strpos(lower(p.title), lower(#{filter.q})) > 0
      OR strpos(lower(p.paper_id), lower(#{filter.q})) > 0
      OR strpos(lower(p.authors), lower(#{filter.q})) > 0
      OR strpos(lower(p.doi), lower(#{filter.q})) > 0)

AND p.source_id = #{filter.sourceId}
AND p.year >= #{filter.yearFrom}
AND p.year <= #{filter.yearTo}
AND p.status = #{filter.status}

mapper.select:
SELECT paper_id, title, authors FROM v2_paper
WHERE source_id = #{sourceId} AND publication_year = #{year}
ORDER BY paper_id

SELECT paper_id FROM v2_paper_read WHERE NOT archived AND source_id = #{sourceId}
AND year >= #{yearFrom}
AND year <= #{yearTo}
ORDER BY paper_id LIMIT #{limit}

mapper.update:
UPDATE v2_paper SET archived_at = CASE WHEN #{archived} THEN now() ELSE NULL END,
                    record_version = record_version + 1, updated_at = now()
WHERE paper_id = #{id}
